const today = new Date();
const plan = window.dailyDevotionalPlan || [];
const specialDevotionals = {
  "Jeremiah 33:3": {
    title: "Call and I Will Answer",
    reflection: [
      "Jeremiah 33:3 is one of those verses that feels made for a quiet cab and an honest heart. God says to call on Him, and the promise is not merely that He hears. He answers.",
      "There are things we cannot solve by staring harder at the dashboard or replaying a worry one more time. The Lord invites us to ask, listen, and trust that He can reveal what we would never find on our own.",
      "Today, let prayer be your first response. Before the next decision, the next difficult conversation, or the next long stretch of road, call on Him. He is not bothered by your need; He welcomes your voice."
    ],
    prayer: "Lord, I am calling on You today. Answer with wisdom, peace, protection, and the kind of hope only You can give."
  }
};

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function getDevotionalDay(date) {
  const start = new Date(date.getFullYear(), 0, 0);
  let day = Math.floor((date - start) / 86400000);
  if (isLeapYear(date.getFullYear())) {
    if (date.getMonth() === 1 && date.getDate() === 29) return 59;
    if (date.getMonth() > 1) day -= 1;
  }
  return Math.min(Math.max(day, 1), 365);
}

function bibleGatewayUrl(reference) {
  return `https://www.biblegateway.com/passage/?search=${encodeURIComponent(reference)}&version=GNT`;
}

function applyTemplate(text, entry) {
  return text.replace("{reference}", entry.reference);
}

function renderDailyDevotional() {
  const day = getDevotionalDay(today);
  const entry = plan[day - 1] || { day: 1, theme: "blessing", reference: "Psalm 1" };
  const theme = devotionalThemes[entry.theme] || devotionalThemes.blessing;
  const special = specialDevotionals[entry.reference];
  const url = bibleGatewayUrl(entry.reference);
  const verseLink = document.getElementById("verseText");
  const referenceLink = document.getElementById("verseReference");

  verseLink.textContent = entry.reference;
  verseLink.href = url;
  verseLink.setAttribute("aria-label", `Read ${entry.reference} in the Good News Translation on BibleGateway`);
  referenceLink.textContent = `Read ${entry.reference} in the Good News Translation on BibleGateway`;
  referenceLink.href = url;

  document.getElementById("devotionalTitle").textContent = special?.title || theme.title;
  const reflection = document.getElementById("devotionalReflection");
  const paragraphs = special?.reflection || theme.reflection.map(paragraph => applyTemplate(paragraph, entry));
  reflection.replaceChildren(...paragraphs.map(paragraph => {
    const element = document.createElement("p");
    element.textContent = paragraph;
    return element;
  }));
  document.getElementById("devotionalPrayer").textContent = special?.prayer || theme.prayer;
  document.getElementById("themeName").textContent = theme.label.toUpperCase();
  document.getElementById("todayDate").textContent = `${today.toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"}).toUpperCase()} · DAY ${String(day).padStart(3, "0")} OF 365`;
  document.getElementById("studyTitle").textContent = `${theme.label} for the Road`;

  if (plan.length !== 365) {
    console.warn(`Expected 365 daily devotionals, found ${plan.length}.`);
  }

  return { entry, theme };
}

const dailyDevotional = renderDailyDevotional();

const nextSunday = new Date(today);
let daysUntilSunday = (7 - today.getDay()) % 7;
if (daysUntilSunday === 0) daysUntilSunday = 7;
nextSunday.setDate(today.getDate() + daysUntilSunday);
nextSunday.setHours(18,0,0,0);
const studyEnd = new Date(nextSunday.getTime() + 60 * 60 * 1000);
const stamp = d => d.toISOString().replace(/[-:]/g,"").replace(/\.\d{3}/,"");
document.getElementById("studyMonth").textContent = nextSunday.toLocaleDateString("en-US",{month:"short"}).toUpperCase();
document.getElementById("studyDay").textContent = nextSunday.getDate();
document.getElementById("studyTime").textContent = nextSunday.toLocaleDateString("en-US",{weekday:"long",month:"short",day:"numeric"}) + " · 6:00 PM PT";
document.getElementById("googleCalendarLink").href = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent("Good News OTR - Sunday Bible Study")}&dates=${stamp(nextSunday)}/${stamp(studyEnd)}&details=${encodeURIComponent(`Join us to study the Bible and this week's Good News OTR daily readings, including ${dailyDevotional.entry.reference}.`)}`;

document.getElementById("prayerForm").addEventListener("submit", event => {
  event.preventDefault();
  const name = document.getElementById("name").value.trim() || "Anonymous";
  const email = document.getElementById("email").value.trim() || "Not provided";
  const request = document.getElementById("request").value.trim();
  const privacy = document.getElementById("privateRequest").checked ? "Yes" : "No";
  const subject = encodeURIComponent(`Good News OTR prayer request from ${name}`);
  const body = encodeURIComponent(`Name: ${name}\nEmail: ${email}\nPrivate request: ${privacy}\n\nPrayer request:\n${request}`);
  document.getElementById("formStatus").textContent = "Opening your email app so you can review and send your request.";
  window.location.href = `mailto:birdsoftware@gmail.com?subject=${subject}&body=${body}`;
});
